INSERT INTO meals (strMeal, strInstructions, ingredients, measures, strCategory, strArea, strMealThumb, strTags, strYoutube, user_id) VALUES
('Spaghetti Carbonara', 'Boil the pasta. In a separate pan, fry the pancetta until crispy. In a bowl, whisk eggs and Parmesan. Mix the pasta with pancetta and egg mixture. Serve with black pepper.', ARRAY['spaghetti', 'pancetta', 'eggs', 'parmesan cheese', 'black pepper'], ARRAY['200g', '100g', '2', '50g', 'to taste'], 'Main', 'Italian', 'https://www.example.com/spaghetti-carbonara.jpg', 'pasta, Italian', 'https://www.youtube.com/watch?v=dQw4w9WgXcQ', '28cd1316-da9e-4ab7-8821-39e1c2035c90'),
('Chicken Curry', 'Fry onions and garlic. Add chicken and curry powder. Stir in coconut milk and let simmer until chicken is cooked. Serve with rice.', ARRAY['chicken breast', 'onion', 'garlic', 'curry powder', 'coconut milk', 'rice'], ARRAY['200g', '1', '2 cloves', '1 tbsp', '200ml', '150g'], 'Main', 'Indian', 'https://www.example.com/chicken-curry.jpg', 'spicy, curry', 'https://www.youtube.com/watch?v=dQw4w9WgXcQ', '28cd1316-da9e-4ab7-8821-39e1c2035c90'),
('Caesar Salad', 'Toss lettuce with Caesar dressing. Add croutons and Parmesan cheese. Garnish with more cheese and pepper.', ARRAY['lettuce', 'caesar dressing', 'croutons', 'parmesan cheese', 'black pepper'], ARRAY['1 head', '3 tbsp', '50g', '20g', 'to taste'], 'Salad', 'American', 'https://www.example.com/caesar-salad.jpg', 'salad, vegetarian', 'https://www.youtube.com/watch?v=dQw4w9WgXcQ', '28cd1316-da9e-4ab7-8821-39e1c2035c90'),
('Beef Tacos', 'Cook ground beef with taco seasoning. Fill tortillas with beef and top with cheese, lettuce, and salsa.', ARRAY['ground beef', 'taco seasoning', 'tortillas', 'cheese', 'lettuce', 'salsa'], ARRAY['300g', '1 tbsp', '4', '50g', '1 head', '3 tbsp'], 'Main', 'Mexican', 'https://www.example.com/beef-tacos.jpg', 'tacos, spicy', 'https://www.youtube.com/watch?v=dQw4w9WgXcQ', '28cd1316-da9e-4ab7-8821-39e1c2035c90'),
('Apple Pie', 'Preheat oven to 180°C. Make a dough with flour, butter, and water. Roll out the dough and place in a pie dish. Fill with sliced apples, sugar, and cinnamon. Bake for 40 minutes.', ARRAY['flour', 'butter', 'water', 'apples', 'sugar', 'cinnamon'], ARRAY['200g', '100g', '50ml', '4', '100g', '1 tsp'], 'Dessert', 'American', 'https://www.example.com/apple-pie.jpg', 'dessert, pie', 'https://www.youtube.com/watch?v=dQw4w9WgXcQ', '28cd1316-da9e-4ab7-8821-39e1c2035c90'),
('Grilled Cheese Sandwich', 'Butter two slices of bread. Place cheese between the slices and grill until golden brown on both sides.', ARRAY['bread', 'cheese', 'butter'], ARRAY['2 slices', '2 slices', '20g'], 'Snack', 'American', 'https://www.example.com/grilled-cheese.jpg', 'cheese, sandwich', 'https://www.youtube.com/watch?v=dQw4w9WgXcQ', '28cd1316-da9e-4ab7-8821-39e1c2035c90'),
('Pierogi Ruskie', '1. Boil potatoes in salted water, drain and mash into puree. \n2. Finely chop the onion and sauté in butter. \n3. Add cottage cheese, onion, salt, and pepper to the potatoes, mix well. \n4. In a bowl, mix flour with water, egg, and salt, knead into an elastic dough. \n5. Roll out the dough into a thin sheet and cut out circles. \n6. Place a teaspoon of filling on each circle and seal the edges. \n7. Cook the pierogi in salted water until they float to the surface. \n8. Serve with onion sautéed in butter and sour cream.', ARRAY['wheat flour', 'egg', 'water', 'salt', 'potatoes', 'cottage cheese', 'onion', 'butter', 'pepper'], ARRAY['500g', '1 pc', '200ml', '1 tsp', '500g', '250g', '1 pc', '2 tbsp', 'to taste'], 'Main', 'Polish', 'https://www.example.com/pierogi-ruskie.jpg', 'traditional, Polish, homemade', 'https://www.youtube.com/watch?v=dQw4w9WgXcQ', '28cd1316-da9e-4ab7-8821-39e1c2035c90');
